using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 removes "Discriminator" property from
            // non-hierarchical containers. Existing documents still have it, so we
            // must opt back in to read them.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Blog");

            // Breaking change 2: EF Core 9 changes id format from "EntityType|Key"
            // to just "Key". Preserve the old format for existing documents.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<BlogIdGenerator>();

            // Breaking change 3: Cosmos DB does not support indexing on arbitrary
            // properties via EF Core. HasIndex() now throws at model validation.
            // REMOVED: entity.HasIndex(b => b.Name);
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; }

    // Needed to preserve the old "Blog|{key}" id format used by EF Core 8
    public string GetCosmosId() => $"Blog|{Id}";
}

