using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // Breaking change 4: EF Core 9 Cosmos provider throws on sync I/O by default.
        // Either switch all calls to async (preferred) or suppress the warning:
        optionsBuilder.ConfigureWarnings(w =>
            w.Ignore(Microsoft.EntityFrameworkCore.Diagnostics.CoreEventId.SyncAndAsyncNotSupported));
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF Core 9 no longer adds a "Discriminator" property
            // to non-hierarchical containers. Existing documents have it, and raw SQL
            // queries like `WHERE c.Discriminator = 'Blog'` depend on it.
            entity.HasDiscriminator<string>("Discriminator").HasValue("Blog");

            // Breaking change 2: EF Core 9 uses just the key as the JSON `id` value.
            // EF Core 8 used "Discriminator|Key" (e.g. "Blog|1"). Existing documents
            // already have id in that format so we must preserve it.
            entity.Property("__id")
                  .HasValueGeneratorFactory<LegacyIdGeneratorFactory>();

            // Breaking change 3: HasIndex() now throws for Cosmos containers because
            // Cosmos does not support EF-managed indexes. REMOVED the old call:
            //   entity.HasIndex(b => b.Name);  // was silently ignored in EF 8
        });
    }
}

class Blog
{
    public string Id { get; set; }
    public string Name { get; set; }
}

/// <summary>
/// Reproduces the EF Core 8 id format: "Discriminator|KeyValue"
/// </summary>
class LegacyIdGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.GetDiscriminatorValue()}|{entry.Property("Id").CurrentValue}";
}

class LegacyIdGeneratorFactory : ValueGeneratorFactory
{
    public override ValueGenerator Create(IProperty property, ITypeBase typeBase)
        => new LegacyIdGenerator();
}

