using Microsoft.EntityFrameworkCore;
using System.Threading.Tasks;

class SyncJob
{
    // Breaking change 4: EF Core 9 Cosmos provider throws on synchronous I/O.
    // Converted to async. If sync is required, suppress the warning in OnConfiguring.
    async Task RunAsync(BlogContext context)
